import re
from .coco_section_generic import YAMLBasedSectionGeneric
from ..utils.logger import logger


class SectionBaseStations(YAMLBasedSectionGeneric):
    def __init__(self, section_name='BASE_STATIONS'):
        super().__init__(section_name)

    def _prepare_section_content(self, enb_config, ue_config, hw_config, execution_config, *args, **kwargs):
        self.radio_id_base = 1
        bs_section_content = []
        for elements in enb_config:
            if re.match(r'^enb', elements):
                enb_id = re.search(r'\d+', elements).group(0)
                mcc = enb_config[f'enb{enb_id}']['mcc']
                mnc = enb_config[f'enb{enb_id}']['mnc']
                bs_section_content.append({
                    'id': int(enb_id),
                    'type': 'external',
                    'plmn': str(f'{str(mcc)}:{str(mnc)}'),
                    's1': enb_config[f'enb{enb_id}']['enb_ip'],
                    'cus_config': self._prepare_cus_subsection_content(ue_config, hw_config, enb_config, execution_config, enb_id),
                    'RRH': self._prepare_rrh_subsection_content(enb_config, enb_id, hw_config),
                    'cells': self._prepare_cells_subsection_content(enb_config, enb_id, ue_config),
                })
        return bs_section_content

    def _count_elements(self, regexp, tab):
        num = 0
        for ele in tab:
            if re.match(regexp, ele):
                num += 1
        return num

    def _prepare_cus_subsection_content(self, ue_ent, hw_config, enb_config, execution_config, enb_id):
        cus_subsection_content = []
        cus_def_count = self._count_elements(r'^cus', ue_ent)
        cus_list_per_enb = self.get_cus_list_per_enb(hw_config)
        for cus_id_per_enb in cus_list_per_enb[enb_id]:
            cus_subsection_dict = {
                'id': int(cus_id_per_enb),
                'lmp_ip': ue_ent[f'cus{cus_id_per_enb}']['ctrl_ip'],
                'trsw_ip': ue_ent[f'cus{cus_id_per_enb}']['trsw_ip']
            }
            if execution_config['hardware_platform'] == 'CUS2':
                cus_subsection_dict['hardware_platform'] = 'CUS2'
            elif execution_config['hardware_platform'] == 'CUS3':
                cus_subsection_dict['hardware_platform'] = 'CUS3'
            if int(cus_def_count) > 1:
                cells = self.get_cell_tab_per_ctrl(cus_id_per_enb, enb_config, hw_config, enb_id)
                if not cells:
                    logger.warning(f"Empty cells declaration for ctrl_{int(cus_id_per_enb)}. Skipping...")
                    continue
                cus_subsection_dict.update({'cells': cells})
            if not execution_config['is_fsm5']:
                cus_subsection_dict.update({'connector': "EIF5"})
            cus_subsection_content.append(cus_subsection_dict)
        return cus_subsection_content

    def _prepare_rrh_subsection_content(self, enb_ent, enb_id, hw_config):
        rrh_subsection_content = []
        for radio_id in sorted(enb_ent[f'enb{enb_id}']['radios'].keys(), key=int):
            radio_ent = enb_ent[f'enb{enb_id}']['radios'][radio_id]
            rrh_subsection_dict = {
                'id': int(self.radio_id_base),
                'name': radio_ent['type'],
                'opt_links': [self._get_opt_links(hw_config, radio_ent, enb_id)],
                'antennas': self._get_antennas(enb_ent[f'enb{enb_id}']['cells'], radio_id, enb_id, enb_ent)
            }
            if radio_ent.get('protocol_type'):
                rrh_subsection_dict.update({'link_type': radio_ent['protocol_type']})
            self.radio_id_base += 1
            rrh_subsection_content.append(rrh_subsection_dict)
        return rrh_subsection_content

    def get_cell_tab_per_ctrl(self, config_cus_id, enb_config, hw_config, enb_id):
        hw_map = self.get_hw_map(enb_config)
        radio_to_cus_map = self.get_radio_to_cus_map(hw_map, hw_config)
        sectors = self.get_enb_cell_id_tab_per_cus(radio_to_cus_map, enb_config, config_cus_id)
        cell_id_to_cus_cell_id_map = self.get_cell_id_to_overall_cell_id_map(enb_config)

        sectors_tab_per_ctrl = []
        for enb_id, enb_cell_tab in sectors.items():
            for cell in enb_cell_tab:
                try:
                    sectors_tab_per_ctrl.append(cell_id_to_cus_cell_id_map[enb_id][cell])
                except Exception:
                    pass
        return sorted(sectors_tab_per_ctrl)

    @staticmethod
    def get_cell_id_to_overall_cell_id_map(enb_config):
        cell_id_to_cus_cell_id_map = {}
        overall_cell_id = 0
        for enb_key in enb_config.keys():
            enb_id = re.search(r'enb(\d+)', enb_key).group(1)
            for enb_cell_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                overall_cell_id += 1
                if enb_id not in cell_id_to_cus_cell_id_map:
                    cell_id_to_cus_cell_id_map[enb_id] = {}
                cell_id_to_cus_cell_id_map[enb_id][enb_cell_id] = overall_cell_id
        return cell_id_to_cus_cell_id_map

    @staticmethod
    def get_enb_cell_id_tab_per_cus(radio_to_cus_map, enb_config, ctrl_cus_id):
        enb_cell_id_tab_per_cus = {}
        for enb_key in radio_to_cus_map.keys():
            for radio, cus_id in radio_to_cus_map[enb_key].items():
                radio_id_from_map = radio.split('_')[1]
                for enb_cell_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                    cell_params = enb_config[enb_key]['cells'][enb_cell_id]
                    enb_id = re.search(r'enb(\d+)', enb_key).group(1)
                    if radio_id_from_map == cell_params['channels'][0]['radio'] and cus_id == ctrl_cus_id:
                        if enb_id not in enb_cell_id_tab_per_cus:
                            enb_cell_id_tab_per_cus[enb_id] = [enb_cell_id]
                        else:
                            enb_cell_id_tab_per_cus[enb_id] = enb_cell_id_tab_per_cus[enb_id] + [enb_cell_id]
        return enb_cell_id_tab_per_cus

    @staticmethod
    def get_radio_to_cus_map(hw_map, hw_config):
        radio_to_cus_map = {}
        for enb_key in hw_map.keys():
            enb_data = {}
            for bbmod, ports in hw_map[enb_key].items():
                for port, radio in ports.items():
                    enb_data[radio] = hw_config['rf_links'][enb_key][bbmod][port].split('.')[0]
            radio_to_cus_map[enb_key] = enb_data
        return radio_to_cus_map

    @staticmethod
    def get_hw_map(enb_config):
        hw_map = {}
        for enb, details in enb_config.items():
            bbmods_smods = {}
            for radio_id, radio_params in details['radios'].items():
                bbmod = radio_params.get('bbmod')
                smod = radio_params.get('smod')
                port = radio_params['port']
                if bbmod:
                    if f"bbmod_{bbmod}" not in bbmods_smods:
                        bbmods_smods[f"bbmod_{bbmod}"] = {}
                    bbmods_smods[f"bbmod_{bbmod}"][f'port{port}'] = f'radio_{radio_id}'
                if smod:
                    if f"smod_{smod}" not in bbmods_smods:
                        bbmods_smods[f"smod_{smod}"] = {}
                    bbmods_smods[f"smod_{smod}"][f'port{port}'] = f'radio_{radio_id}'
            hw_map[enb] = bbmods_smods
        return hw_map

    @staticmethod
    def get_cus_list_per_enb(hw_config):
        cus_list_per_enb = {}
        for enb_key in hw_config['rf_links'].keys():
            enb_id = re.search(r'enb(\d+)', enb_key).group(1)
            for ports in hw_config['rf_links'][enb_key].values():
                for port in ports.values():
                    if enb_id not in cus_list_per_enb:
                        cus_list_per_enb[enb_id] = []
                    cus_list_per_enb[enb_id].append(port.split('.')[0])
            cus_list_per_enb[enb_id] = sorted(set(cus_list_per_enb[enb_id]))
        return cus_list_per_enb

    @staticmethod
    def get_radio_link(hw_config, radio_params, enb_id):
        cus_id_cus_link = hw_config['rf_links'][f'enb{enb_id}'][f'bbmod_{radio_params["bbmod"]}'][
            f'port{radio_params["port"]}']
        radio_link = ".".join(cus_id_cus_link.split('.')[1:])
        cus_id = cus_id_cus_link.split('.')[0]
        return radio_link, cus_id

    @staticmethod
    def _get_opt_links(hw_config, radio_params, enb_id):
        link_speed_map = {
            'eCpri50': 50,
            'eCpri25': 25,
            'eCpri10': 10,
            'Cpri7': 9.8,
            'Cpri6': 6.1,
            'Cpri5': 4.9,
            'Cpri3': 2.4,
            'Cpri2': 1.2,
            '6Gbps': '8x',
            '3Gbps': '4x',
        }
        bbmod_or_smod_key = [key for key in radio_params if 'mod' in key]
        bbmod_or_smod = f'{bbmod_or_smod_key[0]}_{radio_params[bbmod_or_smod_key[0]]}'
        cus_id_cus_link = hw_config['rf_links'][f'enb{enb_id}'][bbmod_or_smod][f'port{radio_params["port"]}']
        opt_links = {'physical_id': float(".".join(cus_id_cus_link.split('.')[1:])),
                     'virtual_id': 1,
                     'link_speed': link_speed_map.get(radio_params.get('link_speed'), 'auto')
                     }
        return opt_links

    @staticmethod
    def get_cells_per_enb(ue_ent, enb_config):
        cus_keys = sorted(key for key in list(ue_ent.keys()) if re.search(r'^cus\d+$', key))
        cells_list_per_enb_dict = {}
        overall_cell_id = 0

        for enb_key in enb_config.keys():
            enb_id = re.search(r'enb(\d+)', enb_key).group(1)
            for enb_cell_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                overall_cell_id += 1
                if cells_list_per_enb_dict.get(enb_id):
                    cells_list_per_enb_dict.update({str(enb_id): cells_list_per_enb_dict[enb_id] + [overall_cell_id]})
                else:
                    cells_list_per_enb_dict[enb_id] = [overall_cell_id]

        mplane_cell_tab = []
        for cus_key in cus_keys:
            cus_ent = ue_ent[cus_key]
            mplane_cell_tab.extend(cus_ent.get('mplane_only', []))
        return cells_list_per_enb_dict, mplane_cell_tab

    def _prepare_cells_subsection_content(self, enb_config, enb_id, ue_ent):
        cells_subsection_content = []
        cells_ent = enb_config[f'enb{enb_id}']['cells']
        cells_per_enb_dict, mplane_cell_tab = self.get_cells_per_enb(ue_ent, enb_config)

        for i, cell_id in enumerate(cells_per_enb_dict[enb_id]):
            cell_content = cells_ent[f'{i + 1}']
            cell_content_dict = {'id': int(cell_id),
                                 'technology': self._get_cell_technology(cell_content),
                                 'tac': int(cell_content['tac'])
                                 }
            if str(cell_id) in mplane_cell_tab:
                cell_content_dict.update({"mplane_only": 'ON'})
            if int(enb_id) > 1:
                cell_content_dict.update({"enb_cell_id": i + 1})
            cells_subsection_content.append(cell_content_dict)
        return cells_subsection_content

    @staticmethod
    def _get_cell_technology(cell_content):
        status = 0
        for key in cell_content.keys():
            if re.match(r'earfc.+', key):
                status = 'lte'
                break
            elif re.match(r'nrarfc.+', key):
                status = 'nr'
                break
            else:
                continue

        if status:
            return status
        else:
            logger.error("Cell technology hasnt been established")
            raise KeyError

    @staticmethod
    def _create_antenna_dict(temp_channel_dict, cell_id_map, enb_id):
        antennas_dict = {}
        for merged_direction in list(temp_channel_dict.values()):
            key = int(merged_direction['port']) - 1
            if key in antennas_dict:
                current_value = antennas_dict.pop(key)
                new_value = {'cell': int(cell_id_map[enb_id][int(merged_direction['cell'])]),
                             'dir': merged_direction['direction']}

                if isinstance(current_value, list):
                    current_value.append(new_value)
                    antennas_dict[key] = current_value
                else:
                    antennas_dict[key] = [current_value, new_value]
            else:
                antennas_dict[int(merged_direction['port']) - 1] = {
                    'cell': int(cell_id_map[enb_id][int(merged_direction['cell'])]),
                    'dir': merged_direction['direction']
                }
        return antennas_dict

    def _get_antennas(self, cells, radio_id, enb_id, enb_config):
        cell_id_map = self._get_cell_id_map(enb_config)
        direction_list = []
        for cell_id, cell_ent in cells.items():
            for channel in cell_ent['channels']:
                if channel['radio'] == radio_id:
                    channel["cell"] = cell_id
                    direction_list.append(channel)

            temp_channel_dict = {}
            # merge separated channel with RX and TX to one line with TXRX
            for direction in direction_list:
                port_key = direction['port'] + direction['cell']
                if port_key not in temp_channel_dict:
                    temp_channel_dict[port_key] = {
                        'direction': '',
                        'port': direction['port'],
                        'radio': direction['radio'],
                        'cell': direction['cell']
                    }
                if direction['direction'] == 'TX':
                    temp_channel_dict[port_key]['direction'] += 'TX'
                elif direction['direction'] == 'RX':
                    temp_channel_dict[port_key]['direction'] += 'RX'

        return self._create_antenna_dict(temp_channel_dict, cell_id_map, enb_id)

    def _get_cell_id_map(self, enb_config):
        cell_id_map = {}
        overall_cell_id = 0
        for enb_key in enb_config.keys():
            enb_id = re.search(r'enb(\d+)', enb_key).group(1)
            for enb_radio_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                overall_cell_id += 1
                if enb_id in cell_id_map:
                    cell_id_map[enb_id][int(enb_radio_id)] = overall_cell_id
                else:
                    cell_id_map[enb_id] = {int(enb_radio_id): overall_cell_id}
        return cell_id_map
